import { handoutPractice, practiceGroups, checkPracticeAnswer } from './handout-practice-data.js';
import { escapeHTML } from './components.js';
import { format } from './core.js';
function nuclei(){function atoms(x,p,n,label){const colors=[...Array(p).fill('#d7b55f'),...Array(n).fill('#8d9dba')];return '<g transform="translate('+x+' 0)"><circle cx="0" cy="88" r="66" fill="#f4f4e9" stroke="#b6c3a8"/>'+colors.map((c,i)=>{const a=i*Math.PI*2/colors.length,r=i%2?44:25;return '<circle cx="'+(Math.cos(a)*r)+'" cy="'+(88+Math.sin(a)*r)+'" r="10" fill="'+c+'" stroke="#fff"/><text x="'+(Math.cos(a)*r)+'" y="'+(92+Math.sin(a)*r)+'" text-anchor="middle" font-size="11" fill="#253c32">'+(i<p?'+':'n')+'</text>';}).join('')+'<text x="0" y="182" text-anchor="middle" font-size="16" fill="#385c44">'+label+'</text><text x="0" y="208" text-anchor="middle" font-size="13" fill="#65775c">'+p+' 個質子＋'+n+' 個中子</text></g>';}
return '<figure class="nuclei-compare"><svg viewBox="0 0 580 230" role="img" aria-label="甲碳12：6質子6中子；乙氧16：8質子8中子">'+atoms(160,6,6,'甲：碳-12')+atoms(420,8,8,'乙：氧-16')+'</svg><figcaption>＋ 是質子，n 是中子。位置與大小為示意；本題近似質子、中子一樣重，忽略電子質量。</figcaption></figure>';}
export function mountHandoutPractice(root,ctx){let index=0,hint=0,solved=new Set([...(ctx.data.handoutSolved||[]),...(ctx.data.practiceSolved||[]).map(i=>'core-'+i)]),drafts=new Map();
root.innerHTML='<section class="guided-practice"><div class="practice-top"><div><span class="eyebrow">把講義題型練熟 · 一次一題</span><h3>選題型，跟著提示算</h3></div><span class="practice-progress" role="status"></span></div><div class="practice-picker"><label>題型<select class="practice-group">'+practiceGroups.map((g,i)=>'<option value="'+i+'">'+g+'</option>').join('')+'</select></label><label>題目<select class="practice-question-picker"></select></label></div><div class="practice-current"></div><div class="practice-paging"><button class="secondary practice-prev">← 上一題</button><span class="practice-position"></span><button class="primary practice-next">下一題 →</button></div></section>';
const host=root.querySelector('.practice-current');
const methods=['克數換成莫耳數：n＝m/M；莫耳數換成克數：m＝nM。M 是莫耳質量，單位 g/mol。','數粒子：N＝nNₐ；由粒子數找莫耳數：n＝N/Nₐ。算一個粒子的平均質量：M/Nₐ。本練習採 Nₐ≈6.02×10²³ mol⁻¹。','原子序數質子；質量數數質子加中子。數很多顆原子時，要把每顆的數量乘上顆數；同樣莫耳數表示同樣多顆。','先用化學式把已知元素的相對質量加總，再用題目的質量比找未知元素。要注意化學式中有幾個 X。','相對數值沒有單位；實際質量用 g，莫耳質量用 g/mol。更改比較用的尺，不會改變原子本身。'];
function updateProgress(){root.querySelector('.practice-progress').textContent='已練會 '+solved.size+' / '+handoutPractice.length;root.querySelector('.practice-position').textContent=(index+1)+' / '+handoutPractice.length;root.querySelector('.practice-prev').disabled=index===0;root.querySelector('.practice-next').disabled=index===handoutPractice.length-1;}
function draw(){hint=0;const q=handoutPractice[index];root.querySelector('.practice-group').value=String(q.group);root.querySelector('.practice-question-picker').innerHTML=handoutPractice.map((x,i)=>({x,i})).filter(({x})=>x.group===q.group).map(({x,i})=>'<option value="'+i+'" '+(i===index?'selected':'')+'>'+((solved.has(x.id)?'✓ ':'')+(i+1)+' · '+escapeHTML(x.q.slice(0,34)))+'</option>').join('');host.innerHTML='<p class="group-method">'+methods[q.group]+'</p><div class="practice-problem" data-problem="'+index+'"><p class="practice-origin">講義第 '+q.page+' 頁的觀念'+(solved.has(q.id)?' · 已答對，可再練一次':'')+'</p><h3>'+escapeHTML(q.q)+'</h3>'+(q.diagram==='nuclei'?nuclei():'')+(q.type==='choice'?'<fieldset class="practice-choices"><legend class="sr-only">'+escapeHTML(q.q)+'</legend>'+q.options.map((o,i)=>'<label><input type="radio" name="handout-answer" value="'+i+'" '+(drafts.get(q.id)===String(i)?'checked':'')+'>'+escapeHTML(o)+'</label>').join('')+'</fieldset>':'<label class="practice-numeric-label">我的答案<div class="practice-numeric"><input class="practice-answer" type="number" min="0" step="any" value="'+escapeHTML(drafts.get(q.id)||'')+'" aria-label="練習答案"><span>'+escapeHTML(q.unit)+'</span></div></label>')+'<div class="button-row"><button class="primary check-problem">檢查答案</button><button class="secondary show-hint">給我第一步提示</button></div><ol class="hint-steps"></ol><p class="problem-feedback" role="status"></p></div>';updateProgress();
host.querySelectorAll('input').forEach(el=>{el.oninput=()=>{drafts.set(q.id,el.value);host.querySelector('.problem-feedback').textContent='';};el.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();host.querySelector('.check-problem').click();}};});
host.querySelector('.show-hint').onclick=e=>{hint=Math.min(q.hints.length,hint+1);host.querySelector('.hint-steps').innerHTML=q.hints.slice(0,hint).map(t=>'<li>'+escapeHTML(t)+'</li>').join('');e.target.textContent=hint===q.hints.length?'提示已全部展開':'再看下一步提示';e.target.disabled=hint===q.hints.length;};
host.querySelector('.check-problem').onclick=()=>{if(!ctx.predict())return;const raw=q.type==='choice'?host.querySelector('input:checked')?.value??'':host.querySelector('.practice-answer').value,r=checkPracticeAnswer(q,raw),feedback=host.querySelector('.problem-feedback');if(!r.valid){feedback.textContent=q.type==='choice'?'先選一個答案，再檢查。':'請填入 0 或大於 0 的有效數字。';return;}const correct=q.type==='choice'?q.options[q.answer]:format(q.answer)+' '+q.unit;feedback.className='problem-feedback '+(r.correct?'correct':'incorrect');feedback.textContent=(r.correct?'✓ 答對了！'+q.hints.at(-1):'正確答案：'+correct+'。'+q.mistake);if(r.correct){solved.add(q.id);ctx.data.handoutSolved=[...solved];ctx.data.practiceSolved=[...solved].filter(id=>id.startsWith('core-')).map(id=>Number(id.slice(5)));ctx.save();updateProgress();if(solved.size===handoutPractice.length)ctx.mark('handout-practice-complete');}else host.querySelector('.hint-steps').innerHTML=q.hints.map(t=>'<li>'+escapeHTML(t)+'</li>').join('');};}
function go(n){index=n;draw();root.querySelector('.practice-top').scrollIntoView({behavior:'instant',block:'start'});}
root.querySelector('.practice-group').onchange=e=>go(handoutPractice.findIndex(q=>q.group===Number(e.target.value)));root.querySelector('.practice-question-picker').onchange=e=>go(Number(e.target.value));root.querySelector('.practice-prev').onclick=()=>go(index-1);root.querySelector('.practice-next').onclick=()=>go(index+1);draw();return{reset(){solved.clear();drafts.clear();index=0;ctx.data.handoutSolved=[];ctx.data.practiceSolved=[];draw();}};
}
